function offerBanner(kind,id){const list=D().offers.filter(o=>(kind==='p'?o.pids.includes(id):(o.sids||[]).includes(id)));if(!list.length)return '';const o=(UI.offerCtx&&list.find(x=>x.id===UI.offerCtx))||list.find(x=>x.status==='active'&&Date.now()<x.to)||list[0],expired=o.status==='ended'||Date.now()>=o.to,p=kind==='p'?prod(id):null,oos=p&&(!p.avail||p.stock<=0),lab=o.type==='percent'?o.value+'% '+t('OFF'):o.type==='flat'?'₹'+o.value+' '+t('OFF'):t('Free delivery');
 const price=p?`<b class="price">${inr(offerPrice(p))}</b> <span class="mrp">${inr(p.price)}</span>`:'';
 return `<div class="card pad stack" style="border-color:${expired||oos?'var(--border-strong)':'var(--offer)'};background:${expired||oos?'var(--surface-2)':'linear-gradient(135deg,var(--offer-soft),var(--surface))'}" role="region" aria-label="${t('Offer')}"><div class="row wrap-r" style="gap:8px"><span class="badge ${expired?'neu':'offer'}">${ic('tag',13)} ${esc(lab)}</span>${expired?`<span class="badge bad">✕ ${t('Offer expired')}</span>`:oos?`<span class="badge warn">${t('Out of stock')}</span>`:`<span class="badge ok">● ${t('Valid till')} ${fdate(o.to)}</span>`}</div><h3>${esc(o.title)}</h3>${expired?`<div class="small t2">${t('This offer ended on')} ${fdate(o.to)}. ${t('The regular price applies.')}</div>`:oos?`<div class="small t2">${t('This offer is on, but the item is out of stock right now.')}</div>`:price}<details class="small"><summary class="bold" style="cursor:pointer;min-height:36px">${t('Terms')}</summary><div class="t2">${esc(o.terms)}</div></details></div>`}
