/* ---- smart search ---- */
const norm=s=>String(s||'').toLowerCase().replace(/[^\p{L}\p{M}\p{N} ]+/gu,' ').replace(/\s+/g,' ').trim();
const toks=s=>norm(s).split(' ').filter(Boolean);
function tokHit(words,txt){const tk=toks(txt);return words.length&&words.every(w=>tk.some(x=>x===w||(w.length>=3&&x.startsWith(w))||(w.length>=5&&lev(x,w)<=1)))}
function kwMatches(q){const n=norm(q);if(!n)return[];const ws=n.split(' ');return D().kw.filter(k=>k.syn.some(sy=>{const s=norm(sy),sw=s.split(' ');return n===s||(s.length>=4&&n.includes(s))||ws.some(w=>sw.some(x=>x===w||(w.length>=4&&x.length>=4&&lev(x,w)<=1)))}))}
function searchAll(q){const words=toks(q),kws=kwMatches(q),subs=new Set(kws.flatMap(k=>k.subs)),shopCats=new Set(kws.flatMap(k=>k.shopCats)),tags=new Set(kws.flatMap(k=>k.tags));
 const own=b=>b&&b.status==='approved';
 const p=D().products.filter(x=>own(biz(x.bid))&&x.status==='active'&&(tokHit(words,[x.name.en,x.name.hi,x.sub,brandOf(x),(x.tags||[]).join(' ')].join(' '))||(x.tags||[]).some(g=>tags.has(g)&&words.some(w=>(x.tags||[]).includes(w)||tags.has(w)||true))&&kws.length>0));
 const pids=new Set(p.map(x=>x.id)),ownersOfP=new Set(p.map(x=>x.bid));
 const b=D().biz.filter(x=>own(x)&&(tokHit(words,[x.name.en,x.name.hi,catName(x.cat)].join(' '))||shopCats.has(x.cat)||ownersOfP.has(x.id)));
 const svcs=allServices().filter(s=>tokHit(words,[s.n,subLabel(s.sub),catName(s.cat),nm(s.owner.name)].join(' '))||subs.has(s.sub));
 const sids=new Set(svcs.map(s=>s.id));
 const vids=allVideos().filter(v=>v.m.status==='approved'&&(tokHit(words,[v.m.title,v.m.cap,(v.m.hashtags||[]).join(' ')].join(' '))||(v.m.tags||[]).some(g=>pids.has(g)||sids.has(g))));
 return{p,b,s:svcs,v:vids,kws,subs:[...subs]}}
let SRCH=null;const srchRes=()=>{const k=UI.q+'|'+(D().products.length)+(D().videosV||'');if(!SRCH||SRCH.k!==k)SRCH={k,r:searchAll(UI.q)};return SRCH.r};
function srchServicesBase(){return UI.q.trim()?searchAll(UI.q).s:allServices()}
function allVideos(){const out=[];[...D().biz,...D().svc].forEach(o=>(o.media||[]).forEach(m=>out.push({m,o})));return out}
const vidCard=(v)=>{const m=v.m,o=v.o;return `<a class="card hover" href="#videos-${m.id}" aria-label="${esc(m.title)}"><div class="art f" style="--h:${m.t==='yt'?0:330};position:relative"><span>${m.thumb}</span><span style="position:absolute;inset:auto 0 0 0;padding:6px 8px;background:linear-gradient(transparent,rgba(0,0,0,.6));color:#fff;font:600 .75rem var(--font-body);display:flex;justify-content:space-between">▶ ${m.views.toLocaleString('en-IN')}<span>${m.dur}s</span></span></div><div class="pad" style="padding:8px 10px"><b class="small truncate" style="display:block">${esc(m.title)}</b><div class="xs muted truncate">${esc(nm(o.name))}</div></div></a>`};
