function suggHtml(v){const n=norm(v);if(!n)return'';const w=toks(v),g=[];const pr=D().products.filter(p=>tokHit(w,p.name.en+' '+(p.tags||[]).join(' '))).slice(0,3).map(p=>p.name.en);const sh=D().biz.filter(b=>tokHit(w,b.name.en)).slice(0,3).map(b=>b.name.en);const sv=allServices().filter(s=>tokHit(w,s.n)).slice(0,3).map(s=>s.n);const ct=[...CATS,...SCATS].filter(c=>tokHit(w,c.en+' '+c.hi)).slice(0,3).map(c=>c.en);const sb=SCATS.flatMap(c=>svcSubs(c.id)).filter(x=>tokHit(w,x.en+' '+x.hi)).slice(0,3).map(x=>x.en);const kw=kwMatches(v).slice(0,2).map(k=>k.key);
 const G=[['Products',pr],['Shops',sh],['Services',sv],['Categories',ct],['Subcategories',sb],['Related searches',kw]].filter(x=>x[1].length);return G.length?`<div class="card" role="listbox" aria-label="${t('Suggestions')}">${G.map(([l,a])=>`<div class="xs muted" style="padding:8px 14px 0">${t(l)}</div>`+a.map(x=>`<button class="btn t block" style="justify-content:flex-start;border-radius:0" role="option" data-act="sq" data-v="${esc(x)}">${ic('search',16)} ${esc(x)}</button>`).join('')).join('')}</div>`:''}
function pFilter(list){const f=UI.fl;let l=list;if(f.cat)l=l.filter(x=>x.cat===f.cat);if(f.dist)l=l.filter(x=>dist(biz(x.bid))<=f.dist);if(f.rating)l=l.filter(x=>pRating(x)>=f.rating);if(f.open)l=l.filter(x=>openState(biz(x.bid)).open);if(f.offers)l=l.filter(hasOffer);if(f.deliver)l=l.filter(x=>delivInfo(biz(x.bid)).ok);if(f.pickup)l=l.filter(x=>biz(x.bid).del.pickup);if(f.pmin!=='')l=l.filter(x=>offerPrice(x)>=+f.pmin);if(f.pmax!=='')l=l.filter(x=>offerPrice(x)<=+f.pmax);const so=UI.sort;if(so==='plow')l=[...l].sort((a,b)=>offerPrice(a)-offerPrice(b));else if(so==='phigh')l=[...l].sort((a,b)=>offerPrice(b)-offerPrice(a));else if(so==='rating')l=[...l].sort((a,b)=>pRating(b)-pRating(a));else if(so==='newest')l=[...l].sort((a,b)=>(+b.id.slice(1))-(+a.id.slice(1)));else l=[...l].sort((a,b)=>dist(biz(a.bid))-dist(biz(b.bid)));return l}
function bFilter(list){const f=UI.fl;let l=list;if(f.cat)l=l.filter(x=>x.cat===f.cat);if(f.dist)l=l.filter(x=>dist(x)<=f.dist);if(f.rating)l=l.filter(x=>x.rating>=f.rating);if(f.open)l=l.filter(x=>openState(x).open);if(f.offers){const ob=new Set(D().offers.filter(o=>o.status==='active').map(o=>o.bid));l=l.filter(x=>ob.has(x.id))}const so=UI.sort;return [...l].sort(so==='rating'?(a,b)=>b.rating-a.rating:(a,b)=>dist(a)-dist(b))}
function sFilter(list){const f=(UI.sfS=UI.sfS||exDef('s'));let l=svcApplyCS(list,f);if(f.dist)l=l.filter(x=>dist(x.owner)<=f.dist);if(f.rating)l=l.filter(x=>x.owner.rating>=f.rating);if(f.avail)l=l.filter(x=>openState(x.owner).open);if(f.verified)l=l.filter(x=>x.owner.verified);if(f.offers)l=l.filter(x=>svOffer(x));const so=UI.sort;if(so==='rating')l=[...l].sort((a,b)=>b.owner.rating-a.owner.rating);else if(so==='plow')l=[...l].sort((a,b)=>(a.ptype==='enquiry'?1e9:a.from)-(b.ptype==='enquiry'?1e9:b.from));else l=[...l].sort((a,b)=>dist(a.owner)-dist(b.owner));return l}
const grpHead=(title,n,tab,why)=>`<div class="sec" style="margin:18px 0 6px"><div><h2>${t(title)} <span class="cnt" style="background:var(--surface-2);color:var(--text)">${n}</span></h2>${why?`<div class="xs muted">${esc(why)}</div>`:''}</div><button class="btn t sm" data-act="stab" data-v="${tab}">${t('See all')} ${ic('cr',16)}</button></div>`;
function resultsHtml(){const q=UI.q.trim();
 if(!q)return `<div class="stack"><div><div class="lbl small">${t('Recent searches')}</div><div class="chips">${S.recentSearch.map(x=>`<button class="chip" data-act="sq" data-v="${esc(x)}">${ic('clock',14)} ${esc(x)}</button>`).join('')}</div></div><div><div class="lbl small">${t('Popular searches')}</div><div class="chips">${POP.map(x=>`<button class="chip" data-act="sq" data-v="${esc(x)}">${ic('search',14)} ${esc(x)}</button>`).join('')}</div></div></div>`;
 const r=srchRes(),P=pFilter(r.p),B=bFilter(r.b),Sv=sFilter(r.s),Vd=r.v,tab=UI.stab,total=P.length+B.length+Sv.length+Vd.length;
 const tabs=`<div class="tabs" role="tablist">${[['all','All',total],['p','Products',P.length],['b','Shops',B.length],['s','Services',Sv.length],['v','Videos',Vd.length]].map(([k,lb,n])=>`<button role="tab" aria-selected="${tab===k}" class="${tab===k?'on':''}" data-act="stab" data-v="${k}">${t(lb)} <span class="cnt" style="background:var(--surface-2);color:var(--text)">${n}</span></button>`).join('')}</div>`;
 if(!total){const rel=[...CATS.slice(0,4),...SCATS.slice(0,2)];return tabs+empty('🔎','No results found','Try fewer filters or a different word.',`<div class="chips" style="flex-wrap:wrap;justify-content:center">${rel.map(c=>`<button class="chip" data-act="catGo" data-id="${c.id}">${c.e} ${esc(nm(c))}</button>`).join('')}</div><div class="chips" style="flex-wrap:wrap;justify-content:center">${POP.slice(0,4).map(x=>`<button class="chip" data-act="sq" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>`)}
 const kwTxt=r.kws.length?r.kws[0].key.toUpperCase():q;
 if(tab==='all')return tabs+(r.kws.length?`<div class="small t2" style="margin-top:4px">${ic('info',14)} ${t('Showing results connected to')} “${esc(r.kws.map(k=>k.key).join(', '))}”: ${esc(r.kws[0].note||'')}</div>`:'')+(P.length?grpHead('Products',P.length,'p')+`<div class="grid auto-s">${P.slice(0,4).map(prodCard).join('')}</div>`:'')+(B.length?grpHead('Shops',B.length,'b',r.kws.length?t('Shops in the related category'):'')+`<div class="shopgrid">${B.slice(0,4).map(shopCard).join('')}</div>`:'')+(Sv.length?grpHead('Services',Sv.length,'s',t('Related services for')+' '+kwTxt)+`<div class="shopgrid">${Sv.slice(0,4).map(serviceCard).join('')}</div>`:'')+(Vd.length?grpHead('Videos',Vd.length,'v')+`<div class="grid auto-s">${Vd.slice(0,4).map(vidCard).join('')}</div>`:'');
 const L={p:[P,x=>`<div class="grid auto-s">${x.map(prodCard).join('')}</div>`],b:[B,x=>`<div class="shopgrid">${x.map(shopCard).join('')}</div>`],s:[Sv,x=>`<div class="shopgrid">${x.map(serviceCard).join('')}</div>`],v:[Vd,x=>`<div class="grid auto-s">${x.map(vidCard).join('')}</div>`]}[tab];
 return tabs+(L[0].length?L[1](L[0]):empty('🔎','Nothing in this tab','Check the All tab or try another word.','<button class="btn p" data-act="stab" data-v="all">'+t('Show all results')+'</button>'))}
