/* services filter component v2: collapsed groups when no category, show more */
function svcSubFilter(ctx,o={}){const st=sfState(ctx),base=sfBase(ctx);UI.sfMore=UI.sfMore||{};let h=`<div class="sf" data-ctx="${ctx}">`;
 if(o.cats)h+=`<div class="sfsec"><h4>${t('Category')}</h4><div class="stack" style="gap:2px">${D().scats.filter(c=>c.on!==false).map(c=>{const n=base.filter(x=>x.cat===c.id).length;return `<label class="check sfi"><input type="checkbox" ${st.cats.includes(c.id)?'checked':''} data-chg="sfCat" data-ctx="${ctx}" data-id="${c.id}" style="accent-color:var(--primary)"><span class="sfl">${c.e} ${esc(nm(c))}</span><span class="sfn">${n}</span></label>`}).join('')}</div></div>`;
 h+=`<div class="sfsec"><h4>${t('Subcategory')}</h4>`;const none=!st.cats.length,ids=none?SCATS.map(c=>c.id):st.cats;
 ids.forEach(cid=>{const all=svcSubs(cid),key=ctx+':'+cid,q=(UI.sfq[key]||'').toLowerCase(),filtered=all.filter(x=>!q||(x.en+' '+x.hi).toLowerCase().includes(q)),more=!!UI.sfMore[key],items=(q||more||filtered.length<=8)?filtered:filtered.slice(0,8),cnt=x=>base.filter(b=>b.cat===cid&&b.sub===x.slug).length,total=base.filter(b=>b.cat===cid).length;if(none&&!total&&!all.some(x=>st.subs.includes(x.slug)))return;
  const inner=`<div class="row between" style="gap:6px"><b class="small">${catOf(cid).e} ${esc(catName(cid))}</b><span class="row" style="gap:0"><button type="button" class="btn t sm" style="min-height:36px;padding:0 8px" data-act="sfAll" data-ctx="${ctx}" data-cat="${cid}">${t('Select all')}</button><button type="button" class="btn t sm" style="min-height:36px;padding:0 8px" data-act="sfClr" data-ctx="${ctx}" data-cat="${cid}">${t('Clear')}</button></span></div>${all.length>8?`<div class="searchbar" style="min-height:42px;margin:6px 0">${ic('search',16)}<input data-in="sfq" data-ctx="${ctx}" data-cat="${cid}" value="${esc(UI.sfq[key]||'')}" placeholder="${t('Search subcategories')}" aria-label="${t('Search subcategories')} ${esc(catName(cid))}"></div>`:''}<div class="stack" style="gap:2px">${items.map(x=>{const n=cnt(x);return `<label class="check sfi ${n?'':'dis'}"><input type="checkbox" ${st.subs.includes(x.slug)?'checked':''} ${n||st.subs.includes(x.slug)?'':'disabled'} data-chg="sfSub" data-ctx="${ctx}" data-s="${x.slug}" style="accent-color:var(--primary)"><span class="sfl">${esc(S.lang==='hi'&&x.hi?x.hi:x.en)}</span><span class="sfn">${n}</span></label>`}).join('')||`<div class="small muted" style="padding:6px">${t('No match')}</div>`}</div>${!q&&filtered.length>8?`<button type="button" class="btn t sm" data-act="sfMore" data-key="${key}" data-ctx="${ctx}" aria-expanded="${more}">${more?t('Show less'):t('Show more')+' ('+(filtered.length-8)+')'}</button>`:''}`;
  h+=none?`<details class="sfgrp" ${all.some(x=>st.subs.includes(x.slug))||UI.sfMore['o:'+key]?'open':''} data-key="${key}"><summary class="small bold" style="min-height:44px;cursor:pointer;display:flex;align-items:center;gap:6px">${catOf(cid).e} ${esc(catName(cid))} <span class="sfn">${total}</span></summary>${inner}</details>`:`<div class="sfgrp" role="group" aria-label="${esc(catName(cid))}">${inner}</div>`});
 return h+'</div></div>'}
A.sfMore=el=>{UI.sfMore[el.dataset.key]=!UI.sfMore[el.dataset.key];sfRedraw(el.dataset.ctx)};
document.addEventListener('toggle',e=>{const d=e.target;if(d.matches&&d.matches('details.sfgrp')){UI.sfMore['o:'+d.dataset.key]=d.open}},true);
